issues=[]
allow={'/tmp':1,'/dev':1,'/home':1,'/etc':1,'..':1,'http':1,'git':1,'python':1,'perl':1,'node':1}
# full text scan of command strings and result content for forbidden tokens
blob_parts=[]
for i,c in enumerate(d['commands']):
    cmd=c['arguments'].get('command','')
    for p in pat_bad:
        for m in re.finditer(p,cmd):
            # exclude benign matches inside result? only command
            issues.append(('cmd',i,c.get('ordinal'),p,m.start(),cmd[max(0,m.start()-40):m.start()+40]))
    res=json.dumps(c.get('result',{}))
    blob_parts.append(res)
# scan result text for path mentions
allres='\n'.join(blob_parts)
for p in pat_bad:
    for m in re.finditer(p,allres):
        issues.append(('res',p,m.start(),allres[max(0,m.start()-50):m.start()+50]))
print('ISSUES:',len(issues))
for x in issues[:80]:
    print(x)
# list all absolute paths referenced in commands
paths=set()
for c in d['commands']:
    for m in re.finditer(r'[/\w.\-]+/[^\s"\']*', c['arguments'].get('command','')):
        s=m.group(0)
        if s.startswith('/'): paths.add(s)
for p in sorted(paths): print('PATH:',p)
PYEOF
